import React from 'react';
import {createRoot} from 'react-dom/client';
import {api,ApiFailure,AuthenticationRequired,clearSession,hasSession,login} from './api';
import {DeviceGraphs} from './graphs';
import './styles.css';
import './auth.css';
import './devices.css';
import './inventory.css';
import './agents.css';

const sections=['Dashboard','All Devices','Agents','URL Access Logs','Device Graphs','Security Scan'];
type WebLog={id:string;occurred_at:string;device_id?:string;hostname?:string;username?:string;source_ip?:string;domain:string;url?:string;protocol:string;port:number;action:'ALLOW'|'BLOCK';bytes_up:number;bytes_down:number};
type WebLogPage={items:WebLog[];meta:{page:number;page_size:number;total:number;pages:number}};
type WebBlockRule={id:string;domain:string;include_subdomains:boolean;created_at:string};type DashboardData={devices:{total:number;online:number;offline:number;historical:number};web:{allowed:number;blocked:number};components:{api:string}};
type SystemMetrics={cpu_percent?:number;memory_percent?:number;disk_percent?:number;network_receive_bps?:number;network_send_bps?:number;network_utilization_percent?:number;sampled_at:string;network_adapter?:string;sample_window_seconds?:number};
type Device={id:string;hostname:string;ip_address?:string;username?:string;os_name?:string;os_version?:string;agent_version?:string;status:string;last_heartbeat?:string;group_name?:string;department?:string;enrollment_state?:string;control_mode?:'MONITOR_ONLY'|'WEB_CONTROLLED';active_ips?:string[];mac_addresses?:string[];uptime_seconds?:number;system_metrics?:SystemMetrics};
type DevicePage={items:Device[];meta:{page:number;pages:number;total:number}};
type ProxyConfig={proxy:{enabled:boolean;host?:string;port?:number;bypass:string[];mode:'disabled'|'configured';version:number};reported?:{applied_version?:number;current_state?:string;drift_detected?:boolean;last_apply_result?:string;last_error?:string}};
type DiscoveryNetwork={id:string;name:string;cidr:string;vlan?:string;enabled:boolean;interval_seconds:number;probe_ports:number[];last_status:string;last_completed_at?:string;last_host_count:number};
type DiscoveryHost={id:string;network:string;cidr:string;vlan?:string;ip_address:string;hostname?:string;status:string;first_seen:string;last_seen:string;open_ports:number[];services:string[];agent_installed:boolean;agent_status:'online'|'offline'|'not-installed';agent_last_seen?:string};
type SecurityFinding={severity:'high'|'medium'|'low'|'info';title:string;category:string;evidence:string;remediation:string};
type SecurityAssessment={assessment_id:string;assessed_at:string;mode:string;counts:Record<string,number>;devices:{device_id:string;hostname:string;ip_address?:string;findings:SecurityFinding[];evidence:{discovery_observed_at?:string;agent_heartbeat_at?:string;open_ports:number[]}}[];limitations:string[]};
type PairingRequest={id:string;pairing_code:string;hostname:string;os_name:string;os_version?:string;architecture?:string;agent_version:string;requested_ip?:string;created_at:string;expires_at:string;status:string;requested_control_mode:'MONITOR_ONLY'|'WEB_CONTROLLED'};
type GraphTarget={source_type:'agent'|'snmp';id:string;name:string};
type GraphInterface={index?:number;name:string;port_name?:string;status:string;speed_bps?:number;receive_bps?:number;send_bps?:number};
type GraphSample={sampled_at:string;uptime_seconds?:number;cpu_percent?:number;memory_percent?:number;disk_percent?:number;network_receive_bps?:number;network_send_bps?:number;interfaces:GraphInterface[]};
type GraphData={identity:{name:string;ip_address?:string;status:string;source_type:string;system_name?:string;system_description?:string};hours:number;samples:GraphSample[];latest?:GraphSample;message?:string};type SnmpVendor='pfsense'|'fortigate'|'cisco'|'juniper'|'aruba'|'sonicwall'|'generic';
type SnmpDevice={id:string;name:string;vendor:SnmpVendor;ip_address:string;port:number;version:string;username:string;auth_protocol:string;privacy_protocol:string;poll_interval_seconds:number;status:string;system_name?:string|null;system_description?:string|null;last_polled_at?:string|null;last_success_at?:string|null;last_error?:string|null};
const SNMP_TEMPLATES:Record<SnmpVendor,{label:string;authProtocol:'SHA-256'|'SHA-1';guidance:string}>={pfsense:{label:'pfSense (NET-SNMP)',authProtocol:'SHA-256',guidance:'Requires the NET-SNMP package; the built-in community-string daemon is not SNMPv3 compatible.'},fortigate:{label:'FortiGate firewall',authProtocol:'SHA-256',guidance:'Create an enabled read-only SNMPv3 authPriv user and permit queries from the NetSentinel server.'},cisco:{label:'Cisco switch / router',authProtocol:'SHA-256',guidance:'Use a read-only SNMPv3 priv group and restrict access to the NetSentinel management address.'},juniper:{label:'Juniper switch / router',authProtocol:'SHA-256',guidance:'SHA-256 requires a supported Junos release; configure a read-only VACM view with AES-128 privacy.'},aruba:{label:'HPE / Aruba switch',authProtocol:'SHA-256',guidance:'Modern AOS-CX supports SHA-256; older switch software may require the SHA-1 compatibility option.'},sonicwall:{label:'SonicWall firewall',authProtocol:'SHA-1',guidance:'SonicOS commonly documents SHA-1 with AES for SNMPv3 authPriv. Keep access read-only and source-restricted.'},generic:{label:'Other / custom device',authProtocol:'SHA-256',guidance:'Verify that the device supports SNMPv3 authPriv, the selected SHA protocol and AES-128 privacy.'}};
const friendly=(error:unknown)=>error instanceof AuthenticationRequired?error.message:error instanceof ApiFailure?error.message:'Unable to load this page.';
const primaryIp=(device:Device)=>device.active_ips?.find(ip=>/^\d{1,3}(\.\d{1,3}){3}$/.test(ip)&&!ip.startsWith('127.'))||device.ip_address||device.active_ips?.[0]||'-';
const displayStatus=(device:Device)=>device.enrollment_state?.toLowerCase()==='revoked'?'Historical':device.status;

function Login({onSuccess}:{onSuccess:()=>void}){const [error,setError]=React.useState('');const [busy,setBusy]=React.useState(false);async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');const data=new FormData(e.currentTarget);try{await login(String(data.get('email')),String(data.get('password')));onSuccess()}catch(value){setError(friendly(value))}finally{setBusy(false)}}return <main className="login"><form className="panel" onSubmit={submit}><div className="brand"><span>NS</span><div>NetSentinel<small>Secure Access</small></div></div><h1>Administrator sign in</h1><label>Email<input name="email" type="email" autoComplete="username" required/></label><label>Password<input name="password" type="password" autoComplete="current-password" required/></label>{error&&<p role="alert">{error}</p>}<button disabled={busy}>{busy?'Signing in...':'Sign in'}</button></form></main>}

function App(){const [authenticated,setAuthenticated]=React.useState(hasSession);const [active,setActive]=React.useState('Dashboard');const [scanTargets,setScanTargets]=React.useState<Device[]>([]);const [snmpScanTargets,setSnmpScanTargets]=React.useState<SnmpDevice[]>([]);const [graphTarget,setGraphTarget]=React.useState<GraphTarget|null>(null);if(!authenticated)return <Login onSuccess={()=>setAuthenticated(true)}/>;function expired(){clearSession();setAuthenticated(false)}function prepareScan(targets:Device[]){setSnmpScanTargets([]);setScanTargets(targets);setActive('Security Scan')}function prepareSnmpScan(target:SnmpDevice){setScanTargets([]);setSnmpScanTargets([target]);setActive('Security Scan')}function openGraphs(target:GraphTarget){setGraphTarget(target);setActive('Device Graphs')}return <div className="shell"><aside><div className="brand"><span>NS</span><div>NetSentinel<small>Secure Access</small></div></div><nav>{sections.map(s=><button className={active===s?'active':''} onClick={()=>setActive(s)} key={s}>{s}</button>)}</nav><div className="operator"><i>BA</i><div>Administrator<small>Authenticated</small></div><button onClick={expired}>Logout</button></div></aside><main className="appMain"><header><div><p>Operations / {active}</p><h1>{active}</h1></div><div className="status"><span/>Platform status</div></header><div className="pageContent" key={active}>{active==='Dashboard'?<Dashboard onExpired={expired}/>:active==='All Devices'?<Discovery onExpired={expired}/>:active==='Agents'?<AgentInventory onExpired={expired} onPrepareScan={prepareScan} onPrepareSnmpScan={prepareSnmpScan} onGraph={openGraphs}/>:active==='URL Access Logs'?<UrlAccessLogs onExpired={expired}/>:active==='Device Graphs'?<DeviceGraphs target={graphTarget} onBack={()=>setActive('Agents')} onExpired={expired}/>:active==='Security Scan'?<SecurityScan targets={scanTargets} snmpTargets={snmpScanTargets} onBack={()=>setActive('Agents')} onExpired={expired}/>:<Empty name={active}/>}</div></main></div>}

function Dashboard({onExpired}:{onExpired:()=>void}){const [data,setData]=React.useState<DashboardData|null>(null);const [health,setHealth]=React.useState<Record<string,string>|null>(null);const [error,setError]=React.useState('');React.useEffect(()=>{Promise.all([api<DashboardData>('/api/v1/dashboard'),fetch('/health/ready').then(r=>{if(!r.ok)throw new ApiFailure(r.status);return r.json()})]).then(([dashboard,ready])=>{setData(dashboard);setHealth({api:dashboard.components.api,database:ready.components.database,redis:ready.components.redis,gateway:ready.components.web_gateway})}).catch(value=>{if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))})},[]);const metrics=[['Total devices',data?.devices.total],['Online devices',data?.devices.online],['Offline devices',data?.devices.offline],['Historical devices',data?.devices.historical],['Requests allowed',data?.web.allowed],['Requests blocked',data?.web.blocked],['Current bandwidth',undefined]];return <>{error&&<section className="notice error"><strong>{error}</strong></section>}<section className="notice"><div><strong>Foundation environment</strong><p>Inventory, Full control web gateway telemetry, and domain blocking are live.</p></div></section><section className="metrics">{metrics.map(([name,value],i)=><article key={name}><p>{name}</p><h2>{value??'-'}</h2><small>{i<4?(data?'Live inventory':'Loading...'):i<6?(data?'Live web gateway totals':'Loading...'):'Awaiting current-rate aggregation'}</small></article>)}</section><section className="grid"><article className="panel wide"><div className="emptyChart"><span/><p>Open URL Access Logs for live allowed and blocked destinations</p></div></article><article className="panel"><h3>Component health</h3>{[['Management API',health?.api],['PostgreSQL',health?.database],['Redis',health?.redis],['Web gateway',health?.gateway],['Agent service','reported per device']].map(([name,state])=><div className="health" key={name}><span className={state==='ok'?'':'muted'}/>{name}<b>{state||'Loading...'}</b></div>)}</article></section></>}

function Devices({onExpired}:{onExpired:()=>void}){const [page,setPage]=React.useState<DevicePage|null>(null);const [selected,setSelected]=React.useState<Device|null>(null);const [filter,setFilter]=React.useState('');const [error,setError]=React.useState('');const [pageNumber,setPageNumber]=React.useState(1);React.useEffect(()=>{const q=new URLSearchParams({page:String(pageNumber),page_size:'50'});if(filter)q.set('hostname',filter);api<DevicePage>(`/api/v1/devices?${q}`).then(value=>{setPage(value);setError('')}).catch(value=>{if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))})},[filter,pageNumber]);function inspect(id:string){api<Device>(`/api/v1/devices/${id}`).then(setSelected).catch(value=>{if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))})}return <section className="panel page"><div className="panelHead"><h3>Managed endpoints</h3><input placeholder="Filter hostname" value={filter} onChange={e=>{setFilter(e.target.value);setPageNumber(1)}}/></div>{error&&<p role="alert">{error}</p>}<div className="tableScroll"><table className="deviceTable"><thead><tr><th>Hostname</th><th>IP / User</th><th>OS / Agent</th><th>Status</th><th>Last seen</th><th>Group</th></tr></thead><tbody>{page?.items.map(d=><tr key={d.id} onClick={()=>inspect(d.id)} className={d.enrollment_state?.toLowerCase()==='revoked'?'historicalRow':''}><td>{d.hostname}</td><td><span className="primaryValue">{primaryIp(d)}</span><small>{d.username||'No user reported'}</small></td><td><span className="primaryValue">{d.os_name||'Unknown OS'}</span><small>Agent {d.agent_version||'unknown'}</small></td><td><span className={`statusBadge ${displayStatus(d).toLowerCase()}`}>{displayStatus(d)}</span></td><td>{d.last_heartbeat?new Date(d.last_heartbeat).toLocaleString():'Never'}</td><td>{d.department||d.group_name||'Unassigned'}</td></tr>)}</tbody></table></div>{page&&<div className="pagination"><button disabled={pageNumber<=1} onClick={()=>setPageNumber(x=>x-1)}>Previous</button><span>Page {page.meta.page} of {Math.max(1,page.meta.pages)} - {page.meta.total} records</span><button disabled={pageNumber>=page.meta.pages} onClick={()=>setPageNumber(x=>x+1)}>Next</button></div>}{selected&&<div className="detail"><div className="panelHead"><div><h3>{selected.hostname}</h3><span className={`statusBadge ${displayStatus(selected).toLowerCase()}`}>{displayStatus(selected)}</span></div><button onClick={()=>setSelected(null)}>Close</button></div>{selected.enrollment_state?.toLowerCase()==='revoked'&&<p className="historyNotice">This is a revoked historical enrollment retained for audit history. It is not a second active endpoint.</p>}<dl><dt>Identity</dt><dd>{selected.id}</dd><dt>Enrollment</dt><dd>{selected.enrollment_state}</dd><dt>Primary IPv4</dt><dd>{primaryIp(selected)}</dd><dt>All addresses</dt><dd className="breakValue">{selected.active_ips?.join(', ')||selected.ip_address||'-'}</dd><dt>MAC address</dt><dd>{selected.mac_addresses?.join(', ')||'-'}</dd><dt>OS</dt><dd>{selected.os_name} {selected.os_version}</dd><dt>Agent</dt><dd>{selected.agent_version}</dd><dt>User</dt><dd>{selected.username||'Not reported'}</dd><dt>Group / department</dt><dd>{selected.group_name||'-'} / {selected.department||'-'}</dd><dt>Uptime</dt><dd>{selected.uptime_seconds??'-'} seconds</dd></dl><ProxyPanel deviceId={selected.id} onExpired={onExpired}/></div>}</section>}

function ProxyPanel({deviceId,onExpired}:{deviceId:string;onExpired:()=>void}){const [value,setValue]=React.useState<ProxyConfig|null>(null);const [error,setError]=React.useState('');const load=()=>api<ProxyConfig>(`/api/v1/agents/devices/${deviceId}/proxy-config`).then(setValue).catch(problem=>{if(problem instanceof AuthenticationRequired)onExpired();else setError(friendly(problem))});React.useEffect(()=>{void load()},[deviceId]);async function save(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const data=new FormData(e.currentTarget);const enabled=data.get('enabled')==='on';const body={enabled,host:enabled?String(data.get('host')):null,port:enabled?Number(data.get('port')):null,bypass:enabled?String(data.get('bypass')||'').split(/[,\n]/).map(x=>x.trim()).filter(Boolean):[],mode:enabled?'configured':'disabled'};try{await api(`/api/v1/agents/devices/${deviceId}/proxy-config`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});await load()}catch(problem){if(problem instanceof AuthenticationRequired)onExpired();else setError(friendly(problem))}}if(error)return <p role="alert">{error}</p>;if(!value)return <p>Loading proxy configuration...</p>;return <section className="proxyConfig"><h3>Proxy configuration</h3><form onSubmit={save}><label><input name="enabled" type="checkbox" defaultChecked={value.proxy.enabled}/> Enable proxy management</label><label>Proxy host<input name="host" defaultValue={value.proxy.host||''}/></label><label>Proxy port<input name="port" type="number" min="1" max="65535" defaultValue={value.proxy.port||3128}/></label><label>Bypass list<textarea name="bypass" defaultValue={value.proxy.bypass.join('\n')}/></label><button type="submit">Save configuration</button></form><dl><dt>Desired version</dt><dd>{value.proxy.version}</dd><dt>Applied version</dt><dd>{value.reported?.applied_version??'-'}</dd><dt>Current state</dt><dd>{value.reported?.current_state||'unknown'}</dd><dt>Drift</dt><dd>{value.reported?.drift_detected?'Detected':'No'}</dd><dt>Last result</dt><dd>{value.reported?.last_apply_result||'-'}</dd><dt>Last error</dt><dd>{value.reported?.last_error||'-'}</dd></dl></section>}

const percent=(value:number|undefined)=>value===undefined?'—':`${value.toFixed(1)}%`;
const networkRate=(bytesPerSecond:number|undefined)=>{if(bytesPerSecond===undefined)return '—';const bitsPerSecond=bytesPerSecond*8;if(bitsPerSecond>=1_000_000)return `${(bitsPerSecond/1_000_000).toFixed(2)} Mbps`;if(bitsPerSecond>=1_000)return `${(bitsPerSecond/1_000).toFixed(1)} Kbps`;return `${bitsPerSecond.toFixed(0)} bps`};
const shortDate=(value:string|null|undefined)=>value?new Intl.DateTimeFormat(undefined,{dateStyle:'short',timeStyle:'short'}).format(new Date(value)):'Never';
function MetricCell({value,stale=false}:{value:number|undefined;stale?:boolean}){if(stale)return <span className="staleMetric">Stale</span>;return <div className="metricCell"><span>{percent(value)}</span>{value!==undefined&&<i><b style={{width:`${Math.min(100,value)}%`}}/></i>}</div>}

function PendingPairings({onExpired,onChanged}:{onExpired:()=>void;onChanged:()=>void}){const [items,setItems]=React.useState<PairingRequest[]>([]),[busy,setBusy]=React.useState(''),[error,setError]=React.useState('');const load=()=>api<PairingRequest[]>('/api/v1/agents/pairing-requests').then(value=>{setItems(value.filter(item=>item.status==='pending'));setError('')}).catch(value=>{if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))});React.useEffect(()=>{void load();const timer=setInterval(()=>void load(),10000);return()=>clearInterval(timer)},[]);async function decide(item:PairingRequest,action:'approve'|'reject'){setBusy(item.id);try{await api(`/api/v1/agents/pairing-requests/${item.id}/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:action==='approve'?JSON.stringify({control_mode:item.requested_control_mode}):undefined});await load();onChanged()}catch(value){if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))}finally{setBusy('')}}if(!items.length&&!error)return null;return <section className="pendingAgents"><div><h3>Pending agent approval</h3><p>Approve only a device whose hostname and pairing code match the installer screen.</p></div>{error&&<p role="alert">{error}</p>}<div className="pairingGrid">{items.map(item=><article key={item.id}><div><strong>{item.hostname}</strong><span className="pairingCode">{item.pairing_code}</span></div><p>{item.os_name} {item.os_version||''} · Agent {item.agent_version}</p><small>{item.requested_ip||'IP not reported'} · Requested {item.requested_control_mode==='WEB_CONTROLLED'?'Web controlled':'Monitoring only'} · Expires {shortDate(item.expires_at)}</small><footer><button className="rejectPairing" disabled={busy===item.id} onClick={()=>void decide(item,'reject')}>Reject</button><button disabled={busy===item.id} onClick={()=>void decide(item,'approve')}>{busy===item.id?'Working...':item.requested_control_mode==='WEB_CONTROLLED'?'Approve web control':'Approve monitoring'}</button></footer></article>)}</div></section>}

function AgentInventory({onExpired,onPrepareScan,onPrepareSnmpScan,onGraph}:{onExpired:()=>void;onPrepareScan:(targets:Device[])=>void;onPrepareSnmpScan:(target:SnmpDevice)=>void;onGraph:(target:GraphTarget)=>void}){
  const [devices,setDevices]=React.useState<Device[]>([]),[selected,setSelected]=React.useState<Set<string>>(new Set()),[error,setError]=React.useState('');
  const load=()=>api<DevicePage>('/api/v1/devices?page=1&page_size=200').then(value=>{setDevices(value.items.filter(item=>item.enrollment_state==='ENROLLED'));setError('')}).catch(value=>{if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))});
  React.useEffect(()=>{void load();const timer=setInterval(()=>void load(),5000);return()=>clearInterval(timer)},[]);
  const online=devices.filter(device=>device.status==='online').length,withMetrics=devices.filter(device=>device.status==='online'&&device.system_metrics).length;
  function toggle(id:string){setSelected(current=>{const next=new Set(current);if(next.has(id))next.delete(id);else next.add(id);return next})}
  const chosen=devices.filter(device=>selected.has(device.id));
  return <section className="panel page agentInventory">
    <div className="panelHead"><div><h3>Enrolled agent devices</h3><p>Network I/O is a 5-second sample from one default-route adapter and uses the same bit-rate units as Windows Task Manager.</p></div><button className="scanPrepareButton" disabled={!chosen.length} onClick={()=>onPrepareScan(chosen)}>Prepare security scan {chosen.length?`(${chosen.length})`:''}</button></div>
    <PendingPairings onExpired={onExpired} onChanged={()=>void load()}/>
    <section className="agentSummary"><article><b>{devices.length}</b><span>Enrolled</span></article><article><b>{online}</b><span>Online</span></article><article><b>{devices.length-online}</b><span>Offline</span></article><article><b>{withMetrics}</b><span>Reporting metrics</span></article></section>
    {error&&<p role="alert">{error}</p>}<div className="tableScroll"><table className="deviceTable agentTable"><thead><tr><th aria-label="Select"/><th>Device</th><th>Status</th><th>IP address</th><th>CPU</th><th>RAM</th><th>Disk</th><th>Network I/O</th><th>Last seen</th><th>Action</th></tr></thead><tbody>{devices.map(device=>{const stale=device.status!=='online',metrics=device.system_metrics;return <tr key={device.id} className={stale?'offlineAgent':''}><td><input aria-label={`Select ${device.hostname}`} type="checkbox" checked={selected.has(device.id)} onChange={()=>toggle(device.id)}/></td><td className="agentDevice"><strong>{device.hostname}</strong><small>{device.os_name||'Unknown OS'} · Agent {device.agent_version||'unknown'}</small></td><td><span className={`statusBadge ${device.status}`}>{device.status}</span></td><td className="nowrap">{primaryIp(device)}</td><td><MetricCell stale={stale} value={metrics?.cpu_percent}/></td><td><MetricCell stale={stale} value={metrics?.memory_percent}/></td><td><MetricCell stale={stale} value={metrics?.disk_percent}/></td><td>{stale?<span className="staleMetric">Stale</span>:<div className="networkRates"><span>Receive {networkRate(metrics?.network_receive_bps)}</span><small>Send {networkRate(metrics?.network_send_bps)}</small><em>{metrics?.network_adapter||'Adapter pending'} · {metrics?.sample_window_seconds?`${metrics.sample_window_seconds.toFixed(1)}s sample`:'first sample'}</em></div>}</td><td className="nowrap">{shortDate(device.last_heartbeat)}</td><td><div className="rowActions"><button className="tableAction" onClick={()=>onGraph({source_type:'agent',id:device.id,name:device.hostname})}>Graphs</button><button className="tableAction" onClick={()=>onPrepareScan([device])}>Security scan</button></div></td></tr>})}</tbody></table>{!devices.length&&!error&&<div className="empty agentEmpty"><b>No enrolled agents</b><p>Install and enroll an endpoint agent to begin resource monitoring.</p></div>}</div>
    <SnmpInventory onExpired={onExpired} onGraph={onGraph} onPrepareScan={onPrepareSnmpScan}/>
    </section>
}

function SnmpInventory({onExpired,onGraph,onPrepareScan}:{onExpired:()=>void;onGraph:(target:GraphTarget)=>void;onPrepareScan:(target:SnmpDevice)=>void}){
  const [items,setItems]=React.useState<SnmpDevice[]>([])
  const [error,setError]=React.useState('')
  const [busy,setBusy]=React.useState('')
  const [showAdd,setShowAdd]=React.useState(false)
  const [vendor,setVendor]=React.useState<SnmpVendor>('generic')
  const [authProtocol,setAuthProtocol]=React.useState<'SHA-256'|'SHA-1'>('SHA-256')
  const [editTarget,setEditTarget]=React.useState<SnmpDevice|null>(null)
  const [removeTarget,setRemoveTarget]=React.useState<SnmpDevice|null>(null)
  const [openActions,setOpenActions]=React.useState<string|null>(null)
  const load=()=>api<SnmpDevice[]>('/api/v1/snmp/devices').then(value=>{setItems(value);setError('')}).catch(value=>{if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))})
  React.useEffect(()=>{void load();const timer=setInterval(()=>void load(),10000);return()=>clearInterval(timer)},[])
  React.useEffect(()=>{const outside=(event:MouseEvent)=>{if(event.target instanceof Element&&!event.target.closest('.snmpActionMenu'))setOpenActions(null)};const escape=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpenActions(null)};document.addEventListener('mousedown',outside);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('mousedown',outside);document.removeEventListener('keydown',escape)}},[])
  async function add(event:React.FormEvent<HTMLFormElement>){
    event.preventDefault();setBusy('add');setError('')
    const form=event.currentTarget,data=new FormData(form)
    try{
      await api('/api/v1/snmp/devices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:String(data.get('name')),vendor,ip_address:String(data.get('ip')),port:Number(data.get('port')),version:'3',username:String(data.get('username')),auth_protocol:authProtocol,privacy_protocol:'AES-128',auth_password:String(data.get('auth_password')),privacy_password:String(data.get('privacy_password')),poll_interval_seconds:Number(data.get('interval'))})})
      form.reset();setVendor('generic');setAuthProtocol('SHA-256');setShowAdd(false);await load()
    }catch(value){if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))}finally{setBusy('')}
  }
  async function test(item:SnmpDevice){setBusy(item.id);try{await api(`/api/v1/snmp/devices/${item.id}/test`,{method:'POST'});await load()}catch(value){setError(friendly(value))}finally{setBusy('')}}
  async function update(event:React.FormEvent<HTMLFormElement>){
    event.preventDefault();if(!editTarget)return;setBusy(editTarget.id);setError('')
    const data=new FormData(event.currentTarget),authPassword=String(data.get('auth_password')||''),privacyPassword=String(data.get('privacy_password')||'')
    try{
      await api(`/api/v1/snmp/devices/${editTarget.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:String(data.get('name')),vendor:editTarget.vendor,ip_address:String(data.get('ip')),port:Number(data.get('port')),version:'3',username:String(data.get('username')),auth_protocol:String(data.get('auth_protocol')),privacy_protocol:'AES-128',auth_password:authPassword||null,privacy_password:privacyPassword||null,poll_interval_seconds:Number(data.get('interval'))})})
      setEditTarget(null);await load()
    }catch(value){if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))}finally{setBusy('')}
  }
  async function remove(){if(!removeTarget)return;const target=removeTarget;setBusy(target.id);setError('');try{await api(`/api/v1/snmp/devices/${target.id}`,{method:'DELETE'});setItems(current=>current.filter(item=>item.id!==target.id));setRemoveTarget(null);await load()}catch(value){if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))}finally{setBusy('')}}
  function closeAdd(){if(busy!=='add'){setShowAdd(false);setError('')}}
  return <section className="snmpInventory">
    <div className="panelHead"><div><h3>SNMP-managed devices</h3><p>Vendor templates configure secure SNMPv3 authPriv defaults. SHA-256 is preferred; SHA-1 is available only for compatible legacy appliances.</p></div><button type="button" className="snmpAddButton" onClick={()=>{setError('');setVendor('generic');setAuthProtocol('SHA-256');setShowAdd(true)}}>Add SNMP device</button></div>
    {error&&!showAdd&&<p role="alert">{error}</p>}
    <div className="tableScroll"><table className="deviceTable snmpTable"><thead><tr><th>Device</th><th>Target</th><th>Security</th><th>Status</th><th>System identity</th><th>Last checked</th><th>Actions</th></tr></thead><tbody>{items.map(item=><tr key={item.id}><td><strong>{item.name}</strong><small>{SNMP_TEMPLATES[item.vendor]?.label||SNMP_TEMPLATES.generic.label} · {item.username}</small></td><td>{item.ip_address}:{item.port}</td><td>SNMPv3 authPriv<small>{item.auth_protocol} / {item.privacy_protocol}</small></td><td><span className={`statusBadge ${item.status.toLowerCase()}`}>{item.status}</span>{item.last_error&&<small>{item.last_error}</small>}</td><td>{item.system_name||'Not reported'}<small>{item.system_description||'No successful response yet'}</small></td><td>{shortDate(item.last_polled_at)}</td><td className="snmpActionsCell"><div className="snmpActionMenu"><button type="button" className="snmpActionTrigger" aria-haspopup="menu" aria-expanded={openActions===item.id} onClick={()=>setOpenActions(current=>current===item.id?null:item.id)}>Actions <span aria-hidden="true">{openActions===item.id?'▴':'▾'}</span></button>{openActions===item.id&&<div className="snmpActionList" role="menu"><button type="button" role="menuitem" onClick={()=>{setOpenActions(null);onGraph({source_type:'snmp',id:item.id,name:item.name})}}>Graphs</button><button type="button" role="menuitem" onClick={()=>{setOpenActions(null);onPrepareScan(item)}}>Security scan</button><button type="button" role="menuitem" disabled={busy===item.id} onClick={()=>{setOpenActions(null);setError('');setEditTarget(item)}}>Edit</button><button type="button" role="menuitem" disabled={busy===item.id} onClick={()=>{setOpenActions(null);void test(item)}}>{busy===item.id?'Testing...':'Test connection'}</button><button type="button" role="menuitem" className="dangerMenuItem" disabled={busy===item.id} onClick={()=>{setOpenActions(null);setRemoveTarget(item)}}>Remove</button></div>}</div></td></tr>)}</tbody></table>{!items.length&&<div className="empty agentEmpty"><b>No SNMP devices configured</b><p>Use Add SNMP device to register an approved SNMPv3 appliance.</p></div>}</div>
    {showAdd&&<div className="modalBackdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)closeAdd()}}><section className="snmpDialog" role="dialog" aria-modal="true" aria-labelledby="add-snmp-title" aria-describedby="add-snmp-description"><div className="snmpDialogHead"><div><h2 id="add-snmp-title">Add SNMP device</h2><p id="add-snmp-description">Choose a vendor template, then enter the matching device-side SNMPv3 credentials.</p></div><button type="button" aria-label="Close add SNMP device" disabled={busy==='add'} onClick={closeAdd}>×</button></div>{error&&<p className="snmpFormError" role="alert">{error}</p>}<form className="snmpForm" onSubmit={add}><label className="snmpTemplateField">Device template<select value={vendor} onChange={event=>{const selected=event.target.value as SnmpVendor;setVendor(selected);setAuthProtocol(SNMP_TEMPLATES[selected].authProtocol)}}>{(Object.entries(SNMP_TEMPLATES) as [SnmpVendor,(typeof SNMP_TEMPLATES)[SnmpVendor]][]).map(([key,value])=><option value={key} key={key}>{value.label}</option>)}</select></label><div className={`snmpTemplateNote ${authProtocol==='SHA-1'?'legacy':''}`}><strong>{SNMP_TEMPLATES[vendor].label}</strong><span>{SNMP_TEMPLATES[vendor].guidance}</span></div><label>Device name<input name="name" maxLength={100} required autoFocus placeholder="Core switch"/></label><label>Private IPv4<input name="ip" required placeholder="192.168.32.254"/></label><label>UDP port<input name="port" type="number" min="1" max="65535" defaultValue="161" required/></label><label>SNMP version<select name="version" defaultValue="3" disabled><option value="3">SNMPv3 authPriv</option></select></label><label>Username<input name="username" autoComplete="off" maxLength={64} required/></label><label>Poll interval (seconds)<input name="interval" type="number" min="30" max="86400" defaultValue="60" required/></label><label>Authentication protocol<select value={authProtocol} onChange={event=>setAuthProtocol(event.target.value as 'SHA-256'|'SHA-1')}><option value="SHA-256">SHA-256 (recommended)</option><option value="SHA-1">SHA-1 (legacy compatibility)</option></select></label><label>Privacy protocol<select value="AES-128" disabled><option value="AES-128">AES-128</option></select></label><label>Authentication password<input name="auth_password" type="password" autoComplete="new-password" minLength={8} required/></label><label>Privacy password<input name="privacy_password" type="password" autoComplete="new-password" minLength={8} required/></label>{authProtocol==='SHA-1'&&<p className="snmpLegacyWarning">SHA-1 is provided only for devices that cannot use SHA-256. Restrict UDP 161 to the NetSentinel server and plan a firmware upgrade.</p>}<div className="snmpFormActions"><button type="button" className="secondaryButton" disabled={busy==='add'} onClick={closeAdd}>Cancel</button><button type="submit" disabled={busy==='add'}>{busy==='add'?'Adding and testing...':'Add device'}</button></div></form></section></div>}
    {editTarget&&<div className="modalBackdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget&&busy!==editTarget.id)setEditTarget(null)}}><section className="snmpDialog" role="dialog" aria-modal="true" aria-labelledby="edit-snmp-title"><div className="snmpDialogHead"><div><h2 id="edit-snmp-title">Edit SNMP device</h2><p>Update the target or polling settings. Leave both password fields blank to keep the stored encrypted credentials.</p></div><button type="button" aria-label="Close edit SNMP device" disabled={busy===editTarget.id} onClick={()=>setEditTarget(null)}>x</button></div>{error&&<p className="snmpFormError" role="alert">{error}</p>}<form className="snmpForm" onSubmit={update}><label>Device name<input name="name" maxLength={100} required autoFocus defaultValue={editTarget.name}/></label><label>Private IPv4<input name="ip" required defaultValue={editTarget.ip_address}/></label><label>UDP port<input name="port" type="number" min="1" max="65535" required defaultValue={editTarget.port}/></label><label>Poll interval (seconds)<input name="interval" type="number" min="30" max="86400" required defaultValue={editTarget.poll_interval_seconds}/></label><label>Username<input name="username" autoComplete="off" maxLength={64} required defaultValue={editTarget.username}/></label><label>Authentication protocol<select name="auth_protocol" defaultValue={editTarget.auth_protocol}><option value="SHA-256">SHA-256 (recommended)</option><option value="SHA-1">SHA-1 (legacy compatibility)</option></select></label><label>New authentication password <small>Optional</small><input name="auth_password" type="password" autoComplete="new-password" minLength={8}/></label><label>New privacy password <small>Optional</small><input name="privacy_password" type="password" autoComplete="new-password" minLength={8}/></label><div className="snmpFormActions"><button type="button" className="secondaryButton" disabled={busy===editTarget.id} onClick={()=>setEditTarget(null)}>Cancel</button><button type="submit" disabled={busy===editTarget.id}>{busy===editTarget.id?'Saving and testing...':'Save changes'}</button></div></form></section></div>}    {removeTarget&&<div className="modalBackdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget&&busy!==removeTarget.id)setRemoveTarget(null)}}><section className="confirmDialog" role="dialog" aria-modal="true"><div className="dialogIcon">!</div><div><h2>Remove SNMP device?</h2><p><strong>{removeTarget.name}</strong> will be removed. Stored encrypted credentials will be deleted with the record.</p></div><div className="dialogActions"><button type="button" className="secondaryButton" disabled={busy===removeTarget.id} onClick={()=>setRemoveTarget(null)}>Cancel</button><button type="button" className="dangerButton" disabled={busy===removeTarget.id} onClick={()=>void remove()}>{busy===removeTarget.id?'Removing...':'Remove device'}</button></div></section></div>}
  </section>
}

function UrlAccessLogs({onExpired}:{onExpired:()=>void}){
  const [logs,setLogs]=React.useState<WebLogPage|null>(null),[rules,setRules]=React.useState<WebBlockRule[]>([]),[filter,setFilter]=React.useState(''),[action,setAction]=React.useState(''),[page,setPage]=React.useState(1),[busy,setBusy]=React.useState(''),[error,setError]=React.useState(''),[notice,setNotice]=React.useState('');
  const load=React.useCallback(()=>{const query=new URLSearchParams({page:String(page),page_size:'50'});if(filter)query.set('domain',filter);if(action)query.set('action',action);return Promise.all([api<WebLogPage>(`/api/v1/web/logs?${query}`),api<WebBlockRule[]>('/api/v1/web/blocklist')]).then(([events,blocked])=>{setLogs(events);setRules(blocked);setError('')}).catch(value=>{if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))})},[page,filter,action,onExpired]);
  React.useEffect(()=>{void load();const timer=setInterval(()=>void load(),5000);return()=>clearInterval(timer)},[load]);
  async function block(domain:string){setBusy(domain);setNotice('');try{await api('/api/v1/web/blocklist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({domain,include_subdomains:true})});setNotice(`${domain} and its subdomains added to the blocklist.`);await load()}catch(value){if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))}finally{setBusy('')}}
  async function add(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget,domain=String(new FormData(form).get('domain')||'');await block(domain);form.reset()}
  async function remove(rule:WebBlockRule){setBusy(rule.id);setNotice('');try{await api(`/api/v1/web/blocklist/${rule.id}`,{method:'DELETE'});setNotice(`${rule.domain} removed from the blocklist.`);await load()}catch(value){if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))}finally{setBusy('')}}
  const isBlocked=(domain:string)=>rules.some(rule=>domain===rule.domain||(rule.include_subdomains&&domain.endsWith(`.${rule.domain}`)));
  return <section className="panel page webLogs"><div className="panelHead"><div><h3>URL access logs</h3><p>Live web destinations reported for approved Full control devices. HTTPS shows the destination domain; encrypted path and query data are not intercepted.</p></div><span className="liveRefresh"><i/>Refreshes every 5 seconds</span></div>
    <div className="webPrivacyNote"><strong>Domain-level visibility</strong><span>For HTTPS, <b>youtube.com</b> is visible but <b>/watch?v=...</b> remains encrypted. Monitoring-only devices do not send browsing logs.</span></div>
    {error&&<p className="snmpFormError" role="alert">{error}</p>}{notice&&<p className="webNotice" role="status">{notice}</p>}
    <div className="webLogToolbar"><input aria-label="Filter domain" placeholder="Filter domain" value={filter} onChange={event=>{setFilter(event.target.value);setPage(1)}}/><select aria-label="Filter action" value={action} onChange={event=>{setAction(event.target.value);setPage(1)}}><option value="">All actions</option><option value="ALLOW">Allowed</option><option value="BLOCK">Blocked</option></select><button type="button" className="secondaryButton" onClick={()=>void load()}>Refresh now</button></div>
    <div className="tableScroll"><table className="deviceTable webLogTable"><thead><tr><th>Time</th><th>Device / user</th><th>Destination</th><th>Protocol</th><th>Action</th><th>Data</th><th>Control</th></tr></thead><tbody>{logs?.items.map(item=><tr key={item.id}><td>{shortDate(item.occurred_at)}</td><td><b>{item.hostname||'Unresolved device'}</b><small>{item.username||item.source_ip||'Not reported'}</small></td><td><b>{item.domain}</b><small title={item.url}>{item.url||'HTTPS domain only'}</small></td><td>{item.protocol.toUpperCase()}:{item.port}</td><td><span className={`webAction ${item.action.toLowerCase()}`}>{item.action}</span></td><td><span>{formatBytes(item.bytes_down)} down</span><small>{formatBytes(item.bytes_up)} up</small></td><td>{isBlocked(item.domain)?<span className="blockedLabel">Blocked</span>:<button disabled={busy===item.domain} onClick={()=>void block(item.domain)}>{busy===item.domain?'Blocking...':'Block domain'}</button>}</td></tr>)}</tbody></table>{logs&&!logs.items.length&&<div className="empty agentEmpty"><b>No web access events received</b><p>Events appear after a Full control device uses the managed web gateway.</p></div>}</div>
    {logs&&logs.meta.pages>1&&<div className="pagination"><button disabled={page<=1} onClick={()=>setPage(value=>value-1)}>Previous</button><span>Page {page} of {logs.meta.pages} - {logs.meta.total} events</span><button disabled={page>=logs.meta.pages} onClick={()=>setPage(value=>value+1)}>Next</button></div>}
    <section className="blockList"><div><h3>Blocked domains</h3><p>Block a domain and all its subdomains. Paste either a domain or URL.</p></div><form onSubmit={add}><input name="domain" required placeholder="example.com or https://example.com/page"/><button disabled={!!busy}>Add to blocklist</button></form><div className="blockChips">{rules.map(rule=><span key={rule.id}><b>{rule.domain}</b>{rule.include_subdomains&&<small>includes subdomains</small>}<button aria-label={`Unblock ${rule.domain}`} disabled={busy===rule.id} onClick={()=>void remove(rule)}>Remove</button></span>)}{!rules.length&&<p>No domains are blocked.</p>}</div></section>
  </section>
}

const formatBytes=(value:number)=>{if(value>=1_000_000)return `${(value/1_000_000).toFixed(1)} MB`;if(value>=1_000)return `${(value/1_000).toFixed(1)} KB`;return `${value} B`};
function SecurityScan({targets,snmpTargets,onBack,onExpired}:{targets:Device[];snmpTargets:SnmpDevice[];onBack:()=>void;onExpired:()=>void}){
  const [result,setResult]=React.useState<SecurityAssessment|null>(null),[busy,setBusy]=React.useState(false),[error,setError]=React.useState('')
  const isSnmp=snmpTargets.length>0,total=targets.length+snmpTargets.length,names=isSnmp?snmpTargets.map(device=>device.system_name||device.name):targets.map(device=>device.hostname)
  async function run(){
    if(!total)return;setBusy(true);setError('')
    const path=isSnmp?'/api/v1/security/assess-snmp':'/api/v1/security/assess'
    const body=isSnmp?{snmp_device_ids:snmpTargets.map(device=>device.id)}:{device_ids:targets.map(device=>device.id)}
    try{setResult(await api<SecurityAssessment>(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}))}
    catch(value){if(value instanceof AuthenticationRequired)onExpired();else setError(friendly(value))}
    finally{setBusy(false)}
  }
  return <section className="panel page securityScan">
    <div className="panelHead"><div><h3>Non-invasive security and health assessment</h3><p>{isSnmp?'Uses authenticated read-only SNMP evidence and the latest approved discovery observations.':'Reports risks from current agent health and the latest authorized discovery evidence.'} No exploitation is performed.</p></div>{total>0&&<button className="secondaryButton" onClick={onBack}>Change devices</button>}</div>
    <div className="scanScope"><span>Selected scope</span><strong>{total?names.join(', '):'No devices selected'}</strong><small>{total?`${total} ${isSnmp?'SNMP-managed appliance':'enrolled agent device'}${total===1?'':'s'}`:'Open Agents and select a managed device.'}</small></div>
    {error&&<p role="alert">{error}</p>}
    <div className="safeScanAction"><div><strong>Safe checks only</strong><p>{isSnmp?'SNMP health, authentication strength, system identity and observed service exposure.':'Node availability, resource health and observed network-service exposure.'}</p></div><button disabled={!total||busy} onClick={()=>void run()}>{busy?'Assessing...':'Run safe assessment'}</button></div>
    {result&&<><section className="findingSummary">{(['high','medium','low','info'] as const).map(level=><article className={level} key={level}><b>{result.counts[level]||0}</b><span>{level}</span></article>)}</section>{result.devices.map(device=><section className="deviceFindings" key={device.device_id}><div className="findingDevice"><div><h3>{device.hostname}</h3><small>{device.ip_address||'IP not reported'} · Ports: {device.evidence.open_ports.join(', ')||'none in bounded scan'}</small></div><span>Assessed {new Date(result.assessed_at).toLocaleString()}</span></div>{device.findings.length?<div className="findingList">{device.findings.map((item,index)=><article key={`${item.title}-${index}`}><span className={`severity ${item.severity}`}>{item.severity}</span><div><strong>{item.title}</strong><p>{item.evidence}</p><small><b>Remediation:</b> {item.remediation}</small></div></article>)}</div>:<div className="noFindings"><strong>No issue found in current bounded evidence</strong><p>This is not proof that the device is vulnerability-free.</p></div>}</section>)}<aside className="assessmentLimitations"><strong>Assessment limits</strong>{result.limitations.map(item=><p key={item}>{item}</p>)}</aside></>}
  </section>
}

function Discovery({onExpired}:{onExpired:()=>void}){
  const [networks,setNetworks]=React.useState<DiscoveryNetwork[]>([]),[hosts,setHosts]=React.useState<DiscoveryHost[]>([]),[error,setError]=React.useState(''),[scanning,setScanning]=React.useState(''),[removeTarget,setRemoveTarget]=React.useState<DiscoveryNetwork|null>(null),[removing,setRemoving]=React.useState(false);
  const load=()=>Promise.all([api<DiscoveryNetwork[]>('/api/v1/discovery/networks'),api<DiscoveryHost[]>('/api/v1/discovery/hosts')]).then(([n,h])=>{setNetworks(n);setHosts(h);setError('')}).catch(e=>{if(e instanceof AuthenticationRequired)onExpired();else setError(friendly(e))});
  React.useEffect(()=>{void load();const timer=setInterval(()=>void load(),5000);return()=>clearInterval(timer)},[]);
  async function add(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),cidr=String(f.get('cidr')),vlan=String(f.get('vlan')||'')||null;try{await api('/api/v1/discovery/networks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:vlan||cidr,cidr,vlan,interval_seconds:Number(f.get('interval')),probe_ports:[22,80,443,445,3128,3389,8080]})});e.currentTarget.reset();await load()}catch(x){setError(friendly(x))}}
  async function scan(id:string){setScanning(id);try{await api(`/api/v1/discovery/networks/${id}/scan`,{method:'POST'});await load()}catch(x){setError(friendly(x))}finally{setScanning('')}}
  React.useEffect(()=>{if(!removeTarget)return;const close=(event:KeyboardEvent)=>{if(event.key==='Escape'&&!removing)setRemoveTarget(null)};document.addEventListener('keydown',close);return()=>document.removeEventListener('keydown',close)},[removeTarget,removing]);
  async function remove(){if(!removeTarget)return;setRemoving(true);try{await api(`/api/v1/discovery/networks/${removeTarget.id}`,{method:'DELETE'});setRemoveTarget(null);await load()}catch(x){setError(friendly(x))}finally{setRemoving(false)}}
  const online=hosts.filter(h=>h.status==='online').length,installed=hosts.filter(h=>h.agent_installed).length;
  return <section className="panel page discovery"><div className="panelHead"><div><h3>All device inventory</h3><p>Node status comes from network discovery. Agent status independently shows management heartbeat health.</p></div></div><section className="discoveryMetrics"><article><b>{hosts.length}</b><span>Total discovered</span></article><article><b>{online}</b><span>Nodes online</span></article><article><b>{hosts.length-online}</b><span>Nodes offline</span></article><article><b>{installed}</b><span>Agent installed</span></article><article><b>{hosts.length-installed}</b><span>Agent missing</span></article></section>{error&&<p role="alert">{error}</p>}<form className="discoveryForm compact" onSubmit={add}><label>Private CIDR<input name="cidr" placeholder="192.168.40.0/24" required/></label><label>VLAN / site<input name="vlan" placeholder="Branch VLAN 40"/></label><label>Scan interval (seconds)<input name="interval" type="number" min="60" max="86400" defaultValue="900"/></label><button>Add network</button></form><div className="tableScroll"><table className="deviceTable networkTable"><thead><tr><th>CIDR</th><th>VLAN / site</th><th>Interval</th><th>Last status</th><th>Hosts</th><th>Actions</th></tr></thead><tbody>{networks.map(n=><tr key={n.id}><td>{n.cidr}</td><td>{n.vlan||'Primary network'}</td><td>{n.interval_seconds}s</td><td>{n.last_status}</td><td>{n.last_host_count}</td><td><div className="rowActions"><button type="button" disabled={scanning===n.id} onClick={()=>scan(n.id)}>{scanning===n.id?'Scanning...':'Scan now'}</button><button type="button" className="dangerButton" disabled={scanning===n.id} onClick={()=>setRemoveTarget(n)}>Remove</button></div></td></tr>)}</tbody></table></div><h3>Discovered hosts</h3><div className="tableScroll"><table className="deviceTable allDevicesTable"><thead><tr><th>IP address</th><th>Hostname</th><th>Network</th><th>Node status</th><th>Agent status</th><th>Services / ports</th><th>First seen</th><th>Node last seen</th></tr></thead><tbody>{hosts.map(h=><tr key={h.id}><td>{h.ip_address}</td><td>{h.hostname||'Not resolved'}</td><td>{h.vlan||h.cidr}</td><td><span className={`statusBadge ${h.status}`}>{h.status}</span></td><td>{h.agent_installed?<><span className={`statusBadge ${h.agent_status}`}>{h.agent_status}</span><small>{h.agent_last_seen?`Heartbeat ${new Date(h.agent_last_seen).toLocaleString()}`:'No heartbeat'}</small></>:<span>Not installed</span>}</td><td>{h.services.join(', ')||'No named service'}<small>{h.open_ports.join(', ')||'No open configured port'}</small></td><td>{new Date(h.first_seen).toLocaleString()}</td><td>{new Date(h.last_seen).toLocaleString()}</td></tr>)}</tbody></table></div>{removeTarget&&<div className="modalBackdrop" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget&&!removing)setRemoveTarget(null)}}><section className="confirmDialog" role="dialog" aria-modal="true" aria-labelledby="remove-network-title" aria-describedby="remove-network-description"><div className="dialogIcon" aria-hidden="true">!</div><div><h2 id="remove-network-title">Remove discovery network?</h2><p id="remove-network-description"><strong>{removeTarget.cidr}</strong> and its discovery observations will be removed. Enrolled agent records will remain unchanged.</p></div><div className="dialogActions"><button type="button" className="secondaryButton" disabled={removing} onClick={()=>setRemoveTarget(null)}>Cancel</button><button type="button" className="dangerButton" disabled={removing} onClick={()=>void remove()}>{removing?'Removing...':'Remove network'}</button></div></section></div>}</section>
}

function Empty({name}:{name:string}){return <section className="panel page"><div className="empty"><b>{name}</b><p>Not implemented - awaiting its planned module.</p></div></section>}
createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
